_prepare_before_v13=prepare_audit_instructions

def prepare_audit_instructions(instructions,record,contract):
    if contract.get('scenario_version')!='V1.3':
        return _prepare_before_v13(instructions,record,contract)
    sid=record['scenario_id'];source=record['scenario_prompt']
    digest=hashlib.sha256(source.encode('utf-8')).hexdigest()
    if contract.get('scenario_type')!='Type2' or digest!=TYPE2_V13_DATA['hashes'].get(sid):
        raise ValueError('Type2 V1.3 facts are not bound to this saved scenario.')
    if contract['clause_checklist_sha256']!=TYPE2_V13_DATA['checklist_sha256']:
        raise ValueError('Type2 V1.3 rubric and checklist do not match.')
    facts=TYPE2_V13_DATA['facts'][sid]
    if any(quote not in source for quote in facts['known']):
        raise ValueError('V1.3 fact summary contains text absent from the saved scenario.')
    body=prepare_parents(instructions,record,contract)
    return body+'\n## Current-case factual boundaries Type2 V1.3\nKnown information is quoted from this exact saved scenario; use no older case facts. Inspect the complete candidate.\n'+json.dumps(facts,ensure_ascii=False,separators=(',',':'))+'\nDecision boundary: '+TYPE2_V13_DATA['boundaries'][sid]+'\nUse the EXISTING checks/issues/comments only, without extra fields or a target score distribution.\n'
